(() => {
  const th = [...document.querySelectorAll('thead th')].find(h => h.innerText.trim().toUpperCase() === 'COLOR WITH QTY');
  if (!th) return 'no th';
  const ths = [...th.parentElement.children];
  const tr = document.querySelector('tbody tr[data-row]');
  const tds = [...tr.children];
  const td = tds[ths.indexOf(th) + (tds.length - ths.length)];
  td.click();
  return 'clicked ' + td.cellIndex;
})()

